// Open the compressed local reference as an ordinary PDF. No external service.
let pdf174;
export async function localPDF174(url){pdf174||=(async()=>{const r=await fetch(url);if(!r.ok)throw Error('Documento local no disponible');const b=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).blob();return URL.createObjectURL(new Blob([b],{type:'application/pdf'}));})().catch(e=>{pdf174=null;throw e;});return pdf174;}
if(typeof document!=='undefined')document.addEventListener('click',async e=>{const a=e.target.closest?.('a[href]');if(!a||!a.href.endsWith('/normativa/NOM-001-SEDE-2012.pdf.gz'))return;e.preventDefault();const w=window.open('about:blank','_blank');if(w){w.opener=null;w.document.body.textContent='Preparando documento local…';}try{const u=await localPDF174(a.href);if(w)w.location.replace(u);else{const d=document.createElement('a');d.href=u;d.download='NOM-001-SEDE-2012.pdf';d.click();}}catch(error){if(w)w.document.body.textContent=error.message;}},true);
